// T010: Thin fetch wrapper around the JSON API.
async function request(method, path, body) {
  const opts = { method, headers: {} };
  if (body !== undefined) {
    opts.headers['Content-Type'] = 'application/json';
    opts.body = JSON.stringify(body);
  }
  const res = await fetch(`/api${path}`, opts);
  let data = null;
  const text = await res.text();
  if (text) {
    try {
      data = JSON.parse(text);
    } catch {
      data = { error: text };
    }
  }
  if (!res.ok) {
    const err = new Error((data && data.error) || `Request failed (${res.status})`);
    err.status = res.status;
    err.data = data;
    throw err;
  }
  return data;
}

export const api = {
  listBookmarks(params = {}) {
    const qs = new URLSearchParams();
    for (const [k, v] of Object.entries(params)) {
      if (v !== undefined && v !== null && v !== '') qs.set(k, v);
    }
    const suffix = qs.toString() ? `?${qs}` : '';
    return request('GET', `/bookmarks${suffix}`);
  },
  getBookmark(id) {
    return request('GET', `/bookmarks/${id}`);
  },
  createBookmark(payload) {
    return request('POST', '/bookmarks', payload);
  },
  updateBookmark(id, payload) {
    return request('PATCH', `/bookmarks/${id}`, payload);
  },
};

