// duplicate URL (409) navigates to the existing bookmark for editing (FR-005).
import { api } from '../lib/api.js';
import { escapeHtml } from '../lib/dom.js';

export async function renderEditor(appEl, { mode, id } = {}) {
  let bookmark = null;
  if (mode === 'edit') {
    bookmark = await api.getBookmark(id);
  }

