input.content:
:root {
  --bg: #f6f7f9;
  --panel: #ffffff;
  --ink: #1c2330;
  --muted: #66707e;
  --line: #e2e6eb;
  --brand: #2f6feb;
  --brand-ink: #ffffff;
  --radius: 10px;
  --font-scale: 1;
}
html[data-text-size='small'] { --font-scale: 0.9; }
html[data-text-size='large'] { --font-scale: 1.15; }

* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: calc(16px * var(--font-scale));
  color: var(--ink);
  background: var(--bg);
}

.app-header {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.75rem 1.25rem;
  background: var(--panel);
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
  z-index: 10;
}
.brand { font-weight: 700; text-decoration: none; color: var(--ink); font-size: 1.1em; }
.main-nav { display: flex; gap: 0.25rem; margin-left: 0.5rem; }
.main-nav a {
  text-decoration: none;
  color: var(--muted);
  padding: 0.35rem 0.7rem;
  border-radius: 8px;
}
.main-nav a.active { color: var(--brand); background: #eaf1fe; font-weight: 600; }
.add-btn { margin-left: auto; }

main { max-width: 820px; margin: 1.5rem auto; padding: 0 1.25rem; }
.view-title { font-size: 1.4em; margin: 0 0 1rem; }
.count { color: var(--muted); font-weight: 400; font-size: 0.75em; }
.loading { color: var(--muted); }

.btn {
  display: inline-block;
  border: 1px solid var(--line);
  background: var(--panel);
  color: var(--ink);
  padding: 0.5rem 0.9rem;
  border-radius: 8px;
  text-decoration: none;
  cursor: pointer;
  font-size: 0.95em;
}
.btn:hover { border-color: #c7ced7; }
.btn-primary { background: var(--brand); color: var(--brand-ink); border-color: var(--brand); }
.btn-primary:hover { background: #245cd0; }
.btn-small { padding: 0.3rem 0.6rem; font-size: 0.85em; }

.bookmark-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 0.6rem; }
.bookmark {
  display: flex;
  gap: 0.85rem;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 0.85rem 1rem;
}
.bm-icon { flex: 0 0 auto; padding-top: 2px; }
.favicon { width: 16px; height: 16px; border-radius: 3px; }
.favicon-fallback { font-size: 14px; }
.bm-main { flex: 1 1 auto; min-width: 0; }
.bm-title { font-weight: 600; color: var(--ink); text-decoration: none; display: inline; }
.bm-title:hover { color: var(--brand); text-decoration: underline; }
.bm-host { display: block; color: var(--muted); font-size: 0.82em; margin-top: 2px; }
.bm-desc { margin: 0.4rem 0 0; color: #45505f; font-size: 0.92em; line-height: 1.4; }
.bm-tags { display: flex; flex-wrap: wrap; gap: 0.3rem; margin-top: 0.5rem; }
.tag {
  background: #eef1f5;
  color: #495260;
  border-radius: 999px;
  padding: 0.1rem 0.55rem;
  font-size: 0.78em;
}
.bm-actions { flex: 0 0 auto; display: flex; align-items: flex-start; }

.empty-state {
  background: var(--panel);
  border: 1px dashed var(--line);
  border-radius: var(--radius);
  padding: 2.5rem 1.5rem;
  text-align: center;
}
.empty-state h2 { margin: 0 0 0.4rem; }
.empty-state p { color: var(--muted); margin: 0 0 1.1rem; }

.form { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 1.25rem; display: flex; flex-direction: column; gap: 0.9rem; }
.form label { display: flex; flex-direction: column; gap: 0.35rem; font-weight: 600; font-size: 0.95em; }
.form input, .form textarea {
  font: inherit;
  padding: 0.55rem 0.65rem;
  border: 1px solid var(--line);
  border-radius: 8px;
  font-weight: 400;
}
.form input:focus, .form textarea:focus { outline: 2px solid #bcd2fb; border-color: var(--brand); }
.hint { color: var(--muted); font-weight: 400; font-size: 0.85em; }
.form-actions { display: flex; gap: 0.6rem; align-items: center; }
.form-error { color: #b42318; background: #fff1f0; border: 1px solid #ffd0cc; border-radius: 8px; padding: 0.5rem 0.7rem; margin: 0; }
.saved-note { color: #0a7d33; margin: 0; }
.preview-img { max-width: 100%; max-height: 200px; border-radius: 8px; border: 1px solid var(--line); }
.error-box { background: #fff1f0; border: 1px solid #ffd0cc; color: #b42318; padding: 1rem; border-radius: var(--radius); }

