// Shared e2e harness: boots the app on an isolated temp DB plus a local fixture
// site, so tests never depend on the public internet (T060 essentials, pulled
// forward for the US1/US2 checks).
import { spawn } from 'node:child_process';
import http from 'node:http';
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
function dirname(p) {
  return p.replace(/\/[^/]*$/, '');
}

const APP_PORT = 4010;
const FIXTURE_PORT = 4210;

/** A small fixture site with predictable OpenGraph metadata. */
export function startFixtureSite() {
  const server = http.createServer((req, res) => {
    const url = new URL(req.url, `http://127.0.0.1:${FIXTURE_PORT}`);
    if (url.pathname === '/article') {
      res.setHeader('content-type', 'text/html; charset=utf-8');
      res.end(`<!doctype html><html><head>
        <title>Fixture Fallback Title</title>
        <meta property="og:title" content="The Fixture Article" />
        <meta property="og:description" content="A predictable fixture description." />
        <meta property="og:image" content="/preview.png" />
        <link rel="icon" href="/favicon.ico" />
      </head><body><h1>Fixture</h1></body></html>`);
      return;
    }
    res.statusCode = 404;
    res.end('not found');
  });
  return new Promise((resolve) => {
    server.listen(FIXTURE_PORT, '127.0.0.1', () =>
      resolve({ server, base: `http://127.0.0.1:${FIXTURE_PORT}` })
    );
  });
}

/** Start the real app on an isolated temp DB. */
export function startApp() {
  const dataDir = mkdtempSync(join(tmpdir(), 'bm-e2e-'));
  const child = spawn('node', ['--disable-warning=ExperimentalWarning', 'src/server/index.js'], {
    cwd: repoRoot,
    env: { ...process.env, PORT: String(APP_PORT), HOST: '127.0.0.1', BM_DATA_DIR: dataDir },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  return new Promise((resolve, reject) => {
    let out = '';
    const onData = (d) => {
      out += d.toString();
      if (out.includes('listening')) resolve({ child, dataDir });
    };
    child.stdout.on('data', onData);
    child.stderr.on('data', onData);
    child.on('exit', (code) => reject(new Error(`app exited early (${code}): ${out}`)));
    setTimeout(() => reject(new Error(`app did not start: ${out}`)), 8000);
  });
}

export function stop(proc) {
  return new Promise((resolve) => {
    if (!proc) return resolve();
    proc.on('exit', () => resolve());
    proc.kill('SIGTERM');
    setTimeout(resolve, 1500);
  });
}

