// T019 [US2]: readable bookmark list — title, description, tags, icon; open in new tab.
import { api } from '../lib/api.js';
import { escapeHtml, truncate } from '../lib/dom.js';

const EMPTY_COPY = {
  all: {
    title: 'No bookmarks yet',
    body: 'Save your first page to get started.',
    cta: true,
  },
  unread: { title: 'Nothing unread', body: 'Bookmarks you mark unread will appear here.' },
  archive: { title: 'Archive is empty', body: 'Archived bookmarks will appear here.' },
};

export async function renderList(appEl, { view = 'all' } = {}) {
  const { items } = await api.listBookmarks({ view });

  const heading =
    view === 'unread' ? 'Unread' : view === 'archive' ? 'Archive' : 'All bookmarks';

  if (!items.length) {
    const e = EMPTY_COPY[view] || EMPTY_COPY.all;
    appEl.innerHTML = `
      <section class="view">
        <h1 class="view-title">${escapeHtml(heading)}</h1>
        <div class="empty-state" data-empty="${view}">
          <h2>${escapeHtml(e.title)}</h2>
          <p>${escapeHtml(e.body)}</p>
          ${e.cta ? '<a class="btn btn-primary" href="#/new">+ Add your first bookmark</a>' : ''}
        </div>
      </section>`;
    return;
  }

  appEl.innerHTML = `
    <section class="view">
      <h1 class="view-title">${escapeHtml(heading)} <span class="count">${items.length}</span></h1>
      <ul class="bookmark-list">
        ${items.map(rowHtml).join('')}
      </ul>
    </section>`;
}

function rowHtml(b) {
  const host = safeHost(b.url);
  const icon = b.icon_url
    ? `<img class="favicon" src="${escapeHtml(b.icon_url)}" alt="" width="16" height="16" loading="lazy" />`
    : `<span class="favicon favicon-fallback" aria-hidden="true">🔖</span>`;
  const tags = (b.tags || [])
    .map((t) => `<span class="tag">${escapeHtml(t)}</span>`)
    .join('');
  const desc = b.description
    ? `<p class="bm-desc" title="${escapeHtml(b.description)}">${escapeHtml(truncate(b.description))}</p>`
    : '';
  return `
    <li class="bookmark" data-id="${b.id}">
      <div class="bm-icon">${icon}</div>
      <div class="bm-main">
        <a class="bm-title" href="${escapeHtml(b.url)}" target="_blank" rel="noopener noreferrer"
           title="${escapeHtml(b.title)}">${escapeHtml(truncate(b.title, 120))}</a>
        <span class="bm-host" title="${escapeHtml(b.url)}">${escapeHtml(host)}</span>
        ${desc}
        <div class="bm-tags">${tags}</div>
      </div>
      <div class="bm-actions">
        <a class="btn btn-small" href="#/edit/${b.id}">Edit</a>
      </div>
    </li>`;
}

function safeHost(url) {
  try {
    return new URL(url).hostname;
  } catch {
    return url;
  }
}

