.tag-entry { position: relative; }
.tag-field { width: 100%; border: none; font: inherit; padding: 0.3rem; }
.tag-field:focus { outline: none; }
.tag-suggestions {
  position: absolute; z-index: 5; left: 0; right: 0; margin: 0; padding: 0; list-style: none;
  background: var(--panel); border: 1px solid var(--line); border-radius: 8px; box-shadow: 0 6px 20px rgba(0,0,0,0.08);
}
.tag-suggestion { display: block; width: 100%; text-align: left; border: none; background: none; padding: 0.45rem 0.6rem; cursor: pointer; font: inherit; }
.tag-suggestion:hover { background: #eef1f5; }

/* Note preview */
.note-field { font-family: ui-monospace, monospace; }
.note-preview-wrap { margin-top: -0.3rem; }
