.note-field { font-family: ui-monospace, monospace; }
.note-preview-wrap { margin-top: -0.3rem; }
.note-preview { border: 1px solid var(--line); border-radius: 8px; padding: 0.6rem 0.8rem; background: #fbfcfe; margin-top: 0.25rem; }
.note-preview :first-child { margin-top: 0; }
.note-preview :last-child { margin-bottom: 0; }
.muted { color: var(--muted); }

