.copies-panel { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 1.25rem; margin-top: 1.2rem; }
.copies-panel h2 { margin: 0 0 0.3rem; font-size: 1.1em; }
.copies-actions { display: flex; gap: 0.5rem; margin: 0.6rem 0; }
