  await page.goto(`/#/edit/${b.id}`);
  await page.click('[data-delete]');
  await expect(page).toHaveURL(/#\/$/);
  // Gone after reload.
  const res = await request.get(`/api/bookmarks/${b.id}`);
  expect(res.status()).toBe(404);
});

